{%- set c = frappe.get_doc("Company", doc.company) -%}
{%- set addr = frappe.db.get_value("Dynamic Link",
      {"link_doctype":"Company","link_name":doc.company,"parenttype":"Address"}, "parent") -%}
{%- set a = frappe.get_doc("Address", addr) if addr else None -%}
<div class="cn-doc">
  <div class="cn-head">
    <div class="cn-company">{{ c.company_name }}</div>
    <div class="cn-subinfo">
      {%- if a %}地址：{{ a.address_line1 }}{% if a.city %}，{{ a.city }}{% endif %}{% if a.pincode %} {{ a.pincode }}{% endif %}{% endif %}
    </div>
    <div class="cn-subinfo">
      {%- if c.tax_id %}税号：{{ c.tax_id }}　{% endif %}
      {%- if c.phone_no %}电话：{{ c.phone_no }}　{% endif %}
      {%- if c.website %}网址：{{ c.website }}{% endif %}
    </div>
    <div class="cn-title">销　售　订　单</div>
  </div>
  </div>

  <table class="cn-meta">
    <tr>
      <td class="lbl">客户名称</td><td class="val" colspan="3">{{ doc.customer_name or doc.customer }}</td>
      <td class="lbl">订单编号</td><td class="val">{{ doc.name }}</td>
    </tr>
    <tr>
      <td class="lbl">联系人</td><td class="val">{{ doc.contact_display or "" }}</td>
      <td class="lbl">联系电话</td><td class="val">{{ doc.contact_mobile or doc.contact_phone or "" }}</td>
      <td class="lbl">订单日期</td><td class="val">{{ frappe.utils.formatdate(doc.transaction_date, "yyyy-MM-dd") }}</td>
    </tr>
    <tr>
      <td class="lbl">交货日期</td><td class="val">{{ frappe.utils.formatdate(doc.delivery_date, "yyyy-MM-dd") if doc.delivery_date else "" }}</td>
      <td class="lbl">付款条款</td><td class="val">{{ doc.payment_terms_template or "" }}</td>
      <td class="lbl">币　别</td><td class="val">{{ doc.currency }}</td>
    </tr>
  </table>

  <table class="cn-items">
    <thead>
      <tr>
        <th style="width:34px">序号</th>
        <th style="width:104px">物料编码</th>
        <th>物料名称 / 规格</th>
        <th style="width:44px">单位</th>
        <th style="width:56px">数量</th>
        <th style="width:88px">单价</th>
        <th style="width:104px">金额</th>
      </tr>
    </thead>
    <tbody>
      {%- for it in doc.items %}
      <tr>
        <td class="c">{{ loop.index }}</td>
        <td>{{ it.item_code }}</td>
        <td>{{ it.item_name }}{% if it.description and it.description != it.item_name %}<div class="desc">{{ it.description }}</div>{% endif %}</td>
        <td class="c">{{ it.uom }}</td>
        <td class="r">{{ "%g"|format(it.qty) }}</td>
        <td class="r">{{ frappe.utils.fmt_money(it.rate, currency=doc.currency) }}</td>
        <td class="r">{{ frappe.utils.fmt_money(it.amount, currency=doc.currency) }}</td>
      </tr>
      {%- endfor %}
      {%- for _ in range(8 - (doc.items|length if doc.items|length < 8 else 8)) %}
      <tr class="blank"><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td></tr>
      {%- endfor %}
    </tbody>
  </table>

  <table class="cn-sum">
    <tr>
      <td class="lbl">合计数量</td><td class="val r">{{ "%g"|format(doc.total_qty) }}</td>
      <td class="lbl">不含税额</td><td class="val r">{{ frappe.utils.fmt_money(doc.net_total, currency=doc.currency) }}</td>
      <td class="lbl">{% if doc.taxes %}增值税{{ "%g"|format(doc.taxes[0].rate) }}%{% else %}税　额{% endif %}</td>
      <td class="val r">{{ frappe.utils.fmt_money(doc.total_taxes_and_charges or 0, currency=doc.currency) }}</td>
    </tr>
    <tr>
      <td class="lbl">价税合计</td>
      <td class="val r big" colspan="5">{{ frappe.utils.fmt_money(doc.grand_total, currency=doc.currency) }}
        {%- if doc.taxes and doc.taxes[0].included_in_print_rate %}<span class="taxnote">（单价为含税价）</span>
        {%- elif doc.taxes %}<span class="taxnote">（单价为不含税价）</span>{% endif %}
      </td>
    </tr>
    <tr>
      <td class="lbl">金额大写</td>
      <td class="val strong big cnword" colspan="5">{{ cncurrency(doc.grand_total) }}</td>
    </tr>
  </table>

  {%- if doc.terms %}
  <div class="cn-terms"><b>备注 / 条款：</b>{{ doc.terms }}</div>
  {%- endif %}

  <table class="cn-sign">
    <tr>
      <td>制单：________</td>
      <td>审核：________</td>
      <td>客户签字确认：________________</td>
      <td>日期：____年__月__日</td>
    </tr>
  </table>
</div>

<style>
.cn-doc{font-family:"Noto Sans CJK SC","WenQuanYi Zen Hei","Microsoft YaHei",sans-serif;
        font-size:9pt;color:#000;line-height:1.45;}
.cn-head{text-align:center;margin-bottom:8px;}
.cn-company{font-size:15pt;font-weight:700;letter-spacing:2px;}
.cn-subinfo{font-size:7.8pt;color:#444;margin-top:1px;}
.cn-title{font-size:17pt;font-weight:700;letter-spacing:8px;margin-top:8px;
          padding-bottom:3px;border-bottom:2px solid #000;display:inline-block;}
.cn-meta,.cn-items,.cn-sum,.cn-sign{width:100%;border-collapse:collapse;}
.cn-meta{margin-top:8px;margin-bottom:-1px;}
.cn-meta td,.cn-items th,.cn-items td,.cn-sum td{border:1px solid #000;padding:3.5px 6px;
        vertical-align:middle;}
.cn-meta .lbl,.cn-sum .lbl{background:#f0f0f0;width:70px;white-space:nowrap;
        font-weight:600;text-align:center;letter-spacing:1px;}
.cn-items{margin-bottom:-1px;}
.cn-items th{background:#e8e8e8;text-align:center;font-weight:700;letter-spacing:1px;
        padding:5px 4px;}
.cn-items td{height:22px;}
.cn-items tbody tr:nth-child(even){background:#fafafa;}
.cn-items .desc{font-size:7.8pt;color:#666;margin-top:1px;}
.cn-items tr.blank td{height:22px;background:#fff;}
.c{text-align:center;}.r{text-align:right;font-variant-numeric:tabular-nums;}
.strong{font-weight:700;}
.cn-sum .big{font-size:10.5pt;font-weight:700;}
.cn-sum .cnword{letter-spacing:1px;}
.cn-terms{border:1px solid #000;border-top:0;padding:5px 6px;font-size:8.2pt;color:#333;}
.cn-sign{margin-top:20px;}
.cn-sign td{padding:6px 6px;font-size:9pt;border:0;}
.cn-foot{margin-top:6px;font-size:7.5pt;color:#888;text-align:center;}
@media print{.cn-items{page-break-inside:auto;} .cn-items tr{page-break-inside:avoid;}}

.cn-items th{white-space:nowrap;}
.cn-items td.r,.cn-sum td.r{white-space:nowrap;}
.cn-sum .lbl{width:64px;}
.cn-sign{margin-top:26px;}

.cn-sum .taxnote{font-size:7.6pt;font-weight:400;color:#666;margin-left:6px;}
.cn-sum .lbl{font-size:8.4pt;}
</style>

