{%- set c = frappe.get_doc("Company", doc.company) -%}
{%- set cust = frappe.get_doc("Customer", doc.customer) if doc.get("customer") else None -%}
{%- set co_addr_name = frappe.db.get_value("Dynamic Link", {"link_doctype":"Company","link_name":doc.company,"parenttype":"Address"}, "parent") -%}
{%- set co_addr = frappe.get_doc("Address", co_addr_name) if co_addr_name else None -%}
{%- set cu_addr_name = frappe.db.get_value("Dynamic Link", {"link_doctype":"Customer","link_name":doc.customer,"parenttype":"Address"}, "parent") if doc.get("customer") else None -%}
{%- set cu_addr = frappe.get_doc("Address", cu_addr_name) if cu_addr_name else None -%}
{%- set tax_rate = doc.taxes[0].rate if doc.taxes else 0 -%}

<div class="fp">
  <div class="fp-top">
    <div class="fp-title">上海增值税专用发票</div>
    <div class="fp-no">
      <div>No <b>0{{ doc.name|replace("-","")|truncate(11, True, "") }}</b></div>
      <div>开票日期：{{ frappe.utils.formatdate(doc.get("posting_date") or doc.transaction_date, "yyyy-MM-dd") }}</div>
    </div>
  </div>

  <table class="fp-main">
    <!-- 购买方 -->
    <tr>
      <td class="side" rowspan="2">购<br/>买<br/>方</td>
      <td class="pk">名　称</td><td class="pv" colspan="3">{{ doc.customer_name or doc.customer }}</td>
    </tr>
    <tr>
      <td class="pk">纳税人识别号</td><td class="pv">{{ cust.tax_id if cust and cust.tax_id else "" }}</td>
      <td class="pk">地址、电话</td>
      <td class="pv">{{ ((cu_addr.address_line1 ~ " " ~ (cu_addr.phone or "")) if cu_addr else "")|truncate(42, True, "") }}</td>
    </tr>
    <tr>
      <td class="side">&nbsp;</td>
      <td class="pk">开户行及账号</td>
      <td class="pv" colspan="3">{{ cust.get("cn_bank_info") if cust else "" }}</td>
    </tr>

    <!-- 明细表头 -->
    <tr class="ih">
      <th colspan="2" style="white-space:nowrap">货物或应税劳务、服务名称</th>
      <th style="width:38px">单位</th>
      <th style="width:46px">数量</th>
      <th style="width:150px">单价 / 金额 / 税率 / 税额</th>
    </tr>
    {%- for it in doc.items %}
    <tr class="ir">
      <td colspan="2" class="iname">{{ it.item_name }}</td>
      <td class="c">{{ it.uom }}</td>
      <td class="c">{{ "%g"|format(it.qty) }}</td>
      <td class="inum">
        <span class="s1">{{ "%.2f"|format(it.net_rate) }}</span>
        <span class="s2">{{ "%.2f"|format(it.net_amount) }}</span>
        <span class="s3">{{ "%g"|format(tax_rate) }}%</span>
        <span class="s4">{{ "%.2f"|format(it.net_amount * tax_rate / 100) }}</span>
      </td>
    </tr>
    {%- endfor %}


    <!-- 合计 -->
    <tr class="tot">
      <td colspan="4" class="r">合　计</td>
      <td class="inum">
        <span class="s1"></span>
        <span class="s2">￥{{ "%.2f"|format(doc.net_total) }}</span>
        <span class="s3"></span>
        <span class="s4">￥{{ "%.2f"|format(doc.total_taxes_and_charges or 0) }}</span>
      </td>
    </tr>
    <tr class="big-tot">
      <td colspan="2" style="white-space:nowrap">价税合计（大写）</td>
      <td colspan="2" class="cnword">{{ cncurrency(doc.grand_total) }}</td>
      <td class="r"><b>（小写）￥{{ "%.2f"|format(doc.grand_total) }}</b></td>
    </tr>

    <!-- 销售方 -->
    <tr>
      <td class="side" rowspan="2">销<br/>售<br/>方</td>
      <td class="pk">名　称</td><td class="pv" colspan="3">{{ c.company_name }}</td>
    </tr>
    <tr>
      <td class="pk">纳税人识别号</td><td class="pv">{{ c.tax_id or "" }}</td>
      <td class="pk">地址、电话</td>
      <td class="pv">{{ ((co_addr.address_line1 ~ " " ~ (c.phone_no or "")) if co_addr else (c.phone_no or ""))|truncate(42, True, "") }}</td>
    </tr>
    <tr>
      <td class="side">&nbsp;</td>
      <td class="pk">开户行及账号</td>
      <td class="pv" colspan="3">{{ c.get("cn_bank_info") or "" }}</td>
    </tr>
  </table>

  <table class="fp-foot">
    <tr>
      <td>收款人：________</td>
      <td>复核：________</td>
      <td>开票人：________</td>
      <td class="r">销售方：（章）</td>
    </tr>
  </table>
</div>

